INSERT INTO `v1_2a19e52e9f1e967e042b6432d8c320d64c2fe8b31af8aeaf909f3ec8d09a51f5` VALUES (1010801033, 2, "けっ。\nな～にが若女将ですか……\n根性のねじ曲がったババ女将のくせに。", 0, 0.2, 1, 11, 1, 0, 10, 1010801);
