INSERT INTO `v1_2a19e52e9f1e967e042b6432d8c320d64c2fe8b31af8aeaf909f3ec8d09a51f5` VALUES (1010801063, 2, "ああっ！？\nあの火の実ですか！\nだったらこの熱さも納得ですよ！\nあいつ、元気だったですか？", 0, 0.2, 1, 11, 1, 0, 10, 1010801);
