INSERT INTO `v1_2a19e52e9f1e967e042b6432d8c320d64c2fe8b31af8aeaf909f3ec8d09a51f5` VALUES (1010806024, 2, "ブラック労働のストレスからの食欲！\n食欲からのぜい肉！\nこの私腹を肥やすのは却下ですわ！\nすっきりごっそり清算しますわよ～！！", 0, 0.2, 1, 11, 1, 0, 10, 1010806);
